import { createHash } from 'node:crypto';
import { constants } from 'node:fs';
import { link, lstat, mkdtemp, open, realpath, rmdir, unlink } from 'node:fs/promises';
import path from 'node:path';
import { PublisherError } from '../util.js';
export async function downloadOwnerMaterial(client, asset, output) {
    // Input has passed the exact shared wire parser; do not treat metadata alone
    // as authority to fetch bytes, or accept a URL/local filename from it.
    if (asset.state !== 'ready' || (typeof asset.expiresAt === 'string' && Date.parse(asset.expiresAt) <= Date.now())) {
        throw new PublisherError('This material is not ready or has expired.', 'sites_asset_not_downloadable');
    }
    const assetId = asset.assetId, byteLength = asset.byteLength, expectedHash = asset.sha256;
    const contentType = asset.contentType;
    const maxBytes = typeof contentType === 'string' && contentType.startsWith('video/') ? 512 * 1024 * 1024 : 25 * 1024 * 1024;
    if (typeof assetId !== 'string' || !/^ast_[a-f0-9]{32}$/.test(assetId) ||
        typeof byteLength !== 'number' || !Number.isSafeInteger(byteLength) || byteLength < 1 || byteLength > maxBytes ||
        typeof expectedHash !== 'string' || !/^[a-f0-9]{64}$/.test(expectedHash) ||
        typeof contentType !== 'string' || !['image/png', 'image/jpeg', 'image/webp', 'image/avif', 'image/gif', 'video/mp4', 'video/webm'].includes(contentType)) {
        throw new PublisherError('Taku returned invalid owner material metadata.', 'sites_owner_response_invalid');
    }
    const target = path.resolve(output);
    let parent;
    try {
        if (await lstat(target).then(() => true, error => {
            if (error.code === 'ENOENT')
                return false;
            throw error;
        }))
            throw new PublisherError('Output already exists. Choose a new filename.', 'sites_asset_output_exists');
        parent = await realpath(path.dirname(target));
    }
    catch (error) {
        if (error instanceof PublisherError)
            throw error;
        throw new PublisherError('Choose a writable, existing output directory.', 'sites_asset_output_invalid');
    }
    const finalPath = path.join(parent, path.basename(target));
    const response = await client.getMaterialContent(assetId);
    let temporary;
    const integrityError = () => new PublisherError('Material bytes do not match the verified metadata. No output was saved.', 'sites_asset_integrity_failed');
    try {
        const encoding = response.headers.get('Content-Encoding');
        const declared = response.headers.get('Content-Length');
        if (response.status !== 200 || !response.body || response.headers.get('Content-Type') !== contentType ||
            (encoding && encoding !== 'identity') || (declared !== null && declared !== String(byteLength)))
            throw integrityError();
        temporary = await mkdtemp(path.join(parent, '.taku-asset-export-'));
        const file = path.join(temporary, 'content');
        const handle = await open(file, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | constants.O_NOFOLLOW, 0o600);
        const reader = response.body.getReader(), hash = createHash('sha256');
        let total = 0;
        try {
            while (true) {
                let part;
                try {
                    part = await reader.read();
                }
                catch {
                    throw integrityError();
                }
                if (part.done)
                    break;
                total += part.value.byteLength;
                if (total > byteLength)
                    throw integrityError();
                hash.update(part.value);
                let offset = 0;
                while (offset < part.value.byteLength) {
                    const written = await handle.write(part.value, offset, part.value.byteLength - offset);
                    if (!written.bytesWritten)
                        throw integrityError();
                    offset += written.bytesWritten;
                }
            }
            if (total !== byteLength || hash.digest('hex') !== expectedHash)
                throw integrityError();
            await handle.sync();
        }
        finally {
            await reader.cancel().catch(() => undefined);
            reader.releaseLock();
            await handle.close();
        }
        // Same-directory hard link is atomic and fails for any existing target,
        // including a symlink. Rename would silently overwrite a raced-in file.
        await link(file, finalPath);
        return { output: target, byteLength, sha256: expectedHash };
    }
    catch (error) {
        if (error instanceof PublisherError)
            throw error;
        if (error && typeof error === 'object' && 'code' in error && error.code === 'EEXIST') {
            throw new PublisherError('Output already exists. Choose a new filename.', 'sites_asset_output_exists');
        }
        throw new PublisherError('Could not save this material. The output was not replaced.', 'sites_asset_download_failed');
    }
    finally {
        await response.body?.cancel().catch(() => undefined);
        if (temporary) {
            await unlink(path.join(temporary, 'content')).catch(() => undefined);
            await rmdir(temporary).catch(() => undefined);
        }
    }
}
